insert into public.bgpi_faculty
(name_bn, designation_bn, department, email, phone, photo_url, profile_url, sort_order, published)
select s.name_bn, s.designation_bn, s.department, s.email, s.phone, s.photo_url, s.profile_url, s.sort_order, true
from faculty_seed s
where not exists (
  select 1 from public.bgpi_faculty f
  where f.name_bn = s.name_bn and f.department = s.department
);
